window.PLAZAS = [{"id": "@plaza-candidates", "district_ref": "@dist-question", "title": "Candidate mechanisms", "subtitle": "", "description": "The candidates the pre-registration started from. Space charge is the null because it needs only drift under space charge; hopping needs, in addition, Anderson localisation to dominate.", "row_axis": "mechanism", "col_axis": "pre-registration", "rows": ["Space charge (SCLC)", "Variable-range hopping", "Poole\u2013Frenkel", "Percolation", "Fowler\u2013Nordheim", "Trap-assisted tunnelling"], "cols": ["role", "how"], "layers": [{"id": "prereg", "label": "Pre-registered", "cells": [["null H0", "V^\u03b1, \u03b1 \u2265 1.5"], ["alt. H1", "ln G vs T"], ["alt. H1", "in analysis"], ["alt. H1", "geometry"], ["excluded", "fields capped"], ["contacts", "qualified"]]}], "highlight": [{"row": 0, "col": 0, "kind": "empty", "label": "DEFAULT", "note": "Space charge is the default expectation for metal contacts injecting into a trap-containing material."}, {"row": 4, "col": 0, "kind": "forbidden", "label": "OUT", "note": "Excluded by design: operating fields capped below its onset."}], "hatch": [], "expected": false, "color": "#b7a6ff", "background": "district", "text_size": 22.0, "corners": [[13.4087092, 52.4915092], [13.4142005, 52.4915092], [13.4142005, 52.4854905], [13.4087092, 52.4854905]], "frame": {"width_m": 372.0, "height_m": 670.0, "grid_x_m": 180.0, "grid_y_m": 84.0, "cell_m": 90.0}, "coordinates": [13.4126948, 52.4883291]}, {"id": "@plaza-results", "district_ref": "@dist-results", "title": "Seven conclusions", "subtitle": "", "description": "The seven conclusions of the final report, one line each. Click a tower on the west shore for the full statement, or follow its bridge back to the study behind it.", "row_axis": "conclusion", "col_axis": "D5, Conclusions", "rows": ["7 \u00b7 drift", "6 \u00b7 hardware", "5 \u00b7 device twin", "4 \u00b7 mechanism", "3 \u00b7 the law", "2 \u00b7 contact", "1 \u00b7 etch depth"], "cols": ["finding", "number"], "layers": [{"id": "res", "label": "Conclusions 1\u20137", "cells": [["two kinds", "17 meV"], ["control voltages", "6\u20138 bits"], ["learned to noise", "0.335 nA"], ["class open", "4 laws fit"], ["tanh step needed", "R\u00b2 0.967"], ["activation sets it", "11% / 5%"], ["switches regime", "55 \u2192 70 nm"]]}], "highlight": [{"row": 3, "col": 0, "kind": "empty", "label": "OPEN", "note": "Hopping is required by no measurement and excluded by none."}], "hatch": [], "expected": false, "color": "#ffd84a", "background": "district", "text_size": 30.0, "corners": [[13.4286371, 52.5201114], [13.4358998, 52.5201114], [13.4358998, 52.5095113], [13.4286371, 52.5095113]], "frame": {"width_m": 492.0, "height_m": 1180.0, "grid_x_m": 180.0, "grid_y_m": 84.0, "cell_m": 150.0}, "coordinates": [13.4335084, 52.5146407]}, {"id": "@plaza-window", "district_ref": "@dist-tlm", "title": "The operating window", "subtitle": "", "description": "Space-charge-limited conduction (SC) appears at 70 and 75 nm of etch depth. The 55 nm ladder is ohmic over its whole bias (anchor 1, contact-limited); the 85 nm ladder is strongly resistive and only weakly nonlinear, with an onset at a critical field four times higher, beyond the usable bias. So the window is bracketed by measurement: from below between 55 and 70 nm, from above between 75 and 85 nm. The narrower 68\u201377 nm comes from interpolating the simulated activation map \u2014 an estimate, not a measurement. Inside the window nonlinearity starts at a fixed critical field of 2.2 MV/m, recovered by three fitted model families.", "row_axis": "etch depth", "col_axis": "Batch 1 ladders (tab:tlm)", "rows": ["55 nm", "70 nm", "75 nm", "\u2248 85 nm"], "cols": ["sample", "regime", "onset field"], "layers": [{"id": "b1", "label": "Two-terminal ladders at four etch depths", "cells": [["B1-45", "ohmic", "\u2014"], ["B1-40", "ohmic \u2192 SC", "2.2 MV/m"], ["B144", "SC", "2.2 MV/m"], ["B1-36", "resistive", "\u2248 4\u00d7 higher"]]}], "highlight": [{"row": 1, "col": 1, "kind": "empty", "label": "WINDOW", "note": "Full ohmic to space-charge progression; anchor 2 of the analysis."}, {"row": 2, "col": 1, "kind": "empty", "label": "WINDOW", "note": "The same space-charge progression at 75 nm."}], "hatch": [], "expected": false, "color": "#4ea3ff", "background": "district", "corners": [[13.4088568, 52.5004923], [13.4152338, 52.5004923], [13.4152338, 52.4964499], [13.4088568, 52.4964499]], "frame": {"width_m": 432.0, "height_m": 450.0, "grid_x_m": 180.0, "grid_y_m": 84.0, "cell_m": 80.0}, "coordinates": [13.4132853, 52.4983004]}, {"id": "@plaza-vrh", "district_ref": "@dist-tcad", "title": "Four laws, one dataset", "subtitle": "", "description": "Candidate conduction laws fitted to the low-bias resistance of the dataset from which the hopping attribution for this device family was originally drawn. R\u00b2 does not discriminate; the residual structure rejects thermal activation, and the three hopping laws cannot be told apart. The pre-registered Bayes factor of ten is not approached, nor its converse: on these data the mechanism is not identifiable.", "row_axis": "candidate law", "col_axis": "fit to low-bias resistance (tab:vrh)", "rows": ["Mott 3D \u00b7 T\u207b\u00bc", "Mott 2D \u00b7 T\u207b\u2153", "Efros\u2013Shklovskii \u00b7 T\u207b\u00bd", "Arrhenius \u00b7 T\u207b\u00b9"], "cols": ["R\u00b2 70\u2013160 K", "R\u00b2 full", "resid. s.d.", "sign changes"], "layers": [{"id": "fit", "label": "The founding cryogenic dataset, 48 points in the 70\u2013160 K window", "cells": [["0.9989", "0.75", "0.018", 20], ["0.9989", "0.72", "0.018", 16], ["0.9983", "0.66", "0.022", 14], ["0.9934", "0.47", "0.044", 5]]}], "highlight": [{"row": 3, "col": 3, "kind": "forbidden", "label": "REJECTED", "note": "Random residuals would change sign about twenty-four times; five sign changes reject thermal activation."}, {"row": 0, "col": 0, "kind": "empty", "label": "SAME"}, {"row": 1, "col": 0, "kind": "empty", "label": "SAME"}, {"row": 2, "col": 0, "kind": "empty", "label": "SAME", "note": "The three hopping exponents are mutually indistinguishable."}], "hatch": [], "expected": false, "color": "#33d0e0", "background": "district", "corners": [[13.408414, 52.5169314], [13.4156766, 52.5169314], [13.4156766, 52.5130686], [13.408414, 52.5130686]], "frame": {"width_m": 492.0, "height_m": 430.0, "grid_x_m": 180.0, "grid_y_m": 84.0, "cell_m": 75.0}, "coordinates": [13.4132853, 52.5148293]}, {"id": "@plaza-bits", "district_ref": "@dist-net", "title": "Weight-precision budget", "subtitle": "", "description": "Rounding is deterministic, so precision was modelled by quantisation-aware training at 4, 6, 8 and 10 bits. All weights together stay within one point of exact weights at 6 bits in the easiest cell (Moons, pre-trained, free gains), 8 bits for most and 10 for the hardest (Spirals, fine-tuned). Quantising the control voltages alone to 4 bits costs 3.5\u20136.8 points; the gains alone cost at most one point (free) or two (non-negative), and nothing from six bits up. Budget: 6\u20138 bits on the biases, 4\u20136 on the gains.", "row_axis": "quantised", "col_axis": "quantisation-aware training (\u00a7 precision)", "rows": ["all weights", "control voltages", "gains, free", "gains, non-neg."], "cols": ["cost at 4 bits", "bits needed"], "layers": [{"id": "qat", "label": "Accuracy cost in points, Moons and Spirals, pre-trained and fine-tuned", "cells": [["4.5\u201313.3", "6 / 8 / 10"], ["3.5\u20136.8", "6\u20138"], ["\u2264 1", "4\u20136"], ["\u2264 2", "4\u20136"]]}], "highlight": [{"row": 1, "col": 1, "kind": "forbidden", "label": "REQUIREMENT", "note": "Six to eight bits on the programmable biases: the hard requirement on the hardware."}], "hatch": [], "expected": false, "color": "#ffb238", "background": "district", "corners": [[13.4094473, 52.5335501], [13.4146433, 52.5335501], [13.4146433, 52.5295077], [13.4094473, 52.5295077]], "frame": {"width_m": 352.0, "height_m": 450.0, "grid_x_m": 180.0, "grid_y_m": 84.0, "cell_m": 80.0}, "coordinates": [13.4132853, 52.5313582]}];

window.TOUR = [{"id": "question", "title": "The question", "text": "Doped silicon can compute. The founding paper said hopping; later work said space charge. Which mechanism rules these devices, and can we get a model to design with: those were the two questions.", "look": "Island 0: what was known before the programme", "focus": ["@spire-q-why", "@spire-q-device", "@spire-q-levers", "@spire-q-founding", "@spire-q-later", "@spire-q-coexist", "@spire-q-gap", "@plaza-candidates"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "guide", "text": "[warm] Welcome to Mind-Matter: nine months of an AI scientist working on silicon devices that compute. I'm Maya.", "do": [{"show": "@dist-question"}]}, {"speaker": "sceptic", "text": "[dryly] And I'm Owen. I'll ask what a reviewer would ask. Where does it start?"}, {"speaker": "guide", "text": "[thoughtful] On this island, with what was known before we began. Computers spend most of their energy moving numbers around. A piece of material can compute directly: voltages in, a current out.", "do": [{"show": "@spire-q-why"}]}, {"speaker": "sceptic", "text": "[curious] What kind of material?"}, {"speaker": "guide", "text": "[confident] Doped silicon, made at the University of Twente: a tiny island with eight contacts. Seven set the function, one reads the answer, and the same chip computes different things as the voltages change.", "do": [{"show": "@spire-q-device"}]}, {"speaker": "sceptic", "text": "[skeptical] So what was missing?"}, {"speaker": "guide", "text": "[serious] The physics. The first paper said the current flows by hopping between dopants. Later work on the same chips pointed to space charge instead, and some studies saw both at once.", "do": [{"highlight": ["@spire-q-founding", "@spire-q-later", "@spire-q-coexist"]}]}, {"speaker": "sceptic", "text": "[curious] Does it matter which?"}, {"speaker": "guide", "text": "[confident] For design, it does. With hopping, you tune the dopants and the disorder. With space charge, the geometry, the contacts and the traps.", "do": [{"show": "@spire-q-levers"}]}, {"speaker": "sceptic", "text": "[dryly] So, two questions."}, {"speaker": "guide", "text": "[warm] Two questions: which mechanism rules these devices, and can we build a model good enough to design with. This table is where we started: space charge as the default, hopping as the alternative, and one candidate ruled out by design.", "do": [{"show": ["@spire-q-gap", "@plaza-candidates"]}, {"plaza_cell": {"plaza": "@plaza-candidates", "row": 4, "col": 0}}]}], "quiz": [], "camera": {"center": [13.4044284, 52.4884998], "zoom": 14.3, "pitch": 55, "bearing": -10}}, {"id": "phlogiston", "title": "Phlogiston, the AI scientist", "text": "An agent in a loop: propose, call a tool, read the result, propose again. Every step recorded, every costly step approved by a person. Two things to test: autonomy and explainability.", "look": "The loop, the gate, the record, and two goals", "focus": ["@spire-ph-loop", "@spire-ph-tools", "@spire-ph-gate", "@spire-ph-record", "@spire-ph-report", "@spire-ct-lit", "@spire-ct-comp", "@chal-autonomy", "@chal-explain"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "sceptic", "text": "[curious] And who did the work?", "do": [{"show": "@dist-phlogiston"}]}, {"speaker": "guide", "text": "[warm] Partly this: Phlogiston, our AI scientist. An agent in a loop. It proposes the next step, calls a tool, reads the result, and proposes again.", "do": [{"show": ["@spire-ph-loop", "@spire-ph-tools"]}]}, {"speaker": "sceptic", "text": "[skeptical] And nobody watches it?"}, {"speaker": "guide", "text": "[confident] Everything it does goes into a record, and every costly step waits at a gate for a person to approve it.", "do": [{"show": ["@spire-ph-record", "@spire-ph-gate"]}]}, {"speaker": "sceptic", "text": "[curious] What were you testing about it?"}, {"speaker": "guide", "text": "[thoughtful] Two things. Autonomy: can it catch its own mistakes? And explainability: does it give you a law you can read, not just a good fit?", "do": [{"show": ["@chal-autonomy", "@chal-explain"]}]}, {"speaker": "sceptic", "text": "[curious] And where did it actually work?"}, {"speaker": "guide", "text": "[confident] Follow the red line. For the simulations, the searches and the benchmark, it only scheduled conventional tools. The first equation campaign, the device models and every network study, it ran itself.", "do": [{"view": "metro"}, {"highlight": ["@spire-grid", "@spire-fabreq", "@spire-agent", "@spire-searches", "@spire-bench", "@spire-perdev", "@spire-setvae", "@spire-geom1", "@spire-geom2", "@spire-netv1", "@spire-akan", "@spire-intercon", "@spire-wpg", "@spire-wpq", "@spire-time"]}]}], "quiz": [], "camera": {"center": [13.3808102, 52.5037711], "zoom": 14.4, "pitch": 50, "bearing": -10}}, {"id": "phases", "title": "Rules, chips, equations, simulation", "text": "Rules fixed in advance, the first chips at four etch depths, an equation hunt and a simulation search. Two failures worth keeping: the wrong knob, and a benchmark the agent lost.", "look": "Phases I to III, and two things that did not work", "focus": ["@spire-prereg", "@spire-batch1", "@spire-agent", "@spire-law", "@spire-grid", "@spire-etch", "@spire-bench"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "guide", "text": "[confident] Now the programme, south to north. First we fixed the rules: what each hypothesis predicts, and what would kill it. Then the first chips, at four etch depths.", "do": [{"view": "city"}, {"show": ["@spire-prereg", "@spire-batch1"]}]}, {"speaker": "guide", "text": "[thoughtful] Then two hunts at once. The agent went after a formula for the current, and the simulator went after the knob that switches the regime.", "do": [{"show": ["@spire-agent", "@spire-grid"]}]}, {"speaker": "sceptic", "text": "[skeptical] Did any of it fail?"}, {"speaker": "guide", "text": "[honest] Plenty. The first knob we tried, etch depth, was the wrong one. The right one is how many dopants at the contact are active.", "do": [{"highlight": ["@spire-etch", "@spire-grid"]}]}, {"speaker": "guide", "text": "[honest] And in equation discovery, a plain package with no physics beat the agent's search, once it was handed the step the agent had found. The agent gave the shape of the law; the optimiser did the search better.", "do": [{"highlight": ["@spire-bench", "@spire-law"]}]}], "quiz": [], "camera": {"center": [13.4, 52.5067355], "zoom": 12.9, "pitch": 45, "bearing": -15}}, {"id": "turn", "title": "The turn", "text": "No new batches, four laws fitting the same data: the programme turned north, to a model of the device itself.", "look": "Interim summary: the road to the mechanism is closed", "focus": ["@spire-interim", "@spire-dev6080", "@spire-doping", "@bneck-noseries", "@bneck-underdet", "@chal-mechanism", "@plaza-vrh"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "sceptic", "text": "[curious] And where did the plan change?"}, {"speaker": "guide", "text": "[serious] Here, in July. The devices that could settle the mechanism, a doping series and two more etch depths, were never made. And on the very dataset where hopping was first claimed, four different laws fit equally well.", "do": [{"show": ["@spire-interim", "@spire-dev6080"]}, {"show": "@plaza-vrh"}]}, {"speaker": "sceptic", "text": "[skeptical] So you gave up on the mechanism?"}, {"speaker": "guide", "text": "[thoughtful] We bounded it, and turned north: from finding the mechanism to building a model of the device itself.", "do": [{"show": ["@chal-mechanism", "@spire-batch2"]}]}], "quiz": [{"ask": {"speaker": "sceptic", "text": "[dryly] Your turn. Click a road that was planned and never built."}, "answer": ["@conduit-doping", "@conduit-dev6080", "@conduit-foundry", "@spire-doping", "@spire-dev6080", "@spire-foundry"], "right": {"speaker": "guide", "text": "[pleased] Exactly. Grey roads are the experiments that never happened, and each has its reason on the card.", "do": [{"show": ["@conduit-doping", "@conduit-dev6080", "@conduit-foundry"]}]}, "wrong": {"speaker": "guide", "text": "[gentle] Close. The grey roads are these: the doping series, the sixty and eighty nanometre devices, and the foundry batch.", "do": [{"show": ["@conduit-doping", "@conduit-dev6080", "@conduit-foundry"]}]}}], "camera": {"center": [13.4056093, 52.5161678], "zoom": 14.6, "pitch": 60, "bearing": -25}}, {"id": "model", "title": "A twin, and what the hardware needs", "text": "Ten new chips, one network per chip, one code for the whole class; then networks built on that model answer the design questions.", "look": "Phases IV and V", "focus": ["@spire-batch2", "@spire-perdev", "@spire-setvae", "@spire-akan", "@spire-intercon", "@spire-wpq", "@spire-time", "@plaza-bits"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "guide", "text": "[warm] Ten new chips, five diameters. One network per chip, learned down to its noise, and one four-number code for the whole class.", "do": [{"show": ["@spire-batch2", "@spire-setvae"]}]}, {"speaker": "sceptic", "text": "[curious] And what is that good for?"}, {"speaker": "guide", "text": "[confident] Designing hardware before you build it. On that model, the networks told us that diameter hardly matters where the interconnect can compensate, and that the control voltages need six to eight bits.", "do": [{"show": ["@spire-akan", "@spire-wpq"]}, {"show": "@plaza-bits"}]}], "quiz": [], "camera": {"center": [13.4, 52.5232645], "zoom": 13.2, "pitch": 50, "bearing": -10}}, {"id": "results", "title": "What the programme established", "text": "Seven conclusions: where the regime switches, what sets the boundary, a law with a step in it, a twin of the device class, hardware requirements, two kinds of drift, and the mechanism bounded but open.", "look": "The results island: seven conclusions", "focus": ["@spire-r1", "@spire-r2", "@spire-r3", "@spire-r4", "@spire-r5", "@spire-r6", "@spire-r7", "@spire-d5", "@plaza-results"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "sceptic", "text": "[curious] So what did you actually find?", "do": [{"show": "@dist-results"}]}, {"speaker": "guide", "text": "[confident] Seven things, on this island. Etch depth switches the regime, somewhere between fifty-five and seventy nanometres, and the active dopants at the contact set the boundary.", "do": [{"highlight": ["@spire-r1", "@spire-r2"]}]}, {"speaker": "guide", "text": "[thoughtful] A closed-form law with a step in it, which no sum of power laws can mimic. A model of each chip down to its noise, and of the whole class. And hard numbers for the hardware.", "do": [{"highlight": ["@spire-r3", "@spire-r5", "@spire-r6"]}]}, {"speaker": "sceptic", "text": "[skeptical] And the mechanism?"}, {"speaker": "guide", "text": "[honest] Bounded, not found. The regime looks like space charge; whether hopping is underneath, no measurement says yes, and none says no.", "do": [{"show": "@spire-r4"}, {"plaza_cell": {"plaza": "@plaza-results", "row": 3, "col": 0}}]}], "quiz": [], "camera": {"center": [13.431737, 52.515], "zoom": 14.1, "pitch": 50, "bearing": -20}}, {"id": "kept", "title": "What we kept: negative results", "text": "With an agent, a failed probe is cheap and the record keeps every one. Eight crosses stay on the map; five reported results were taken back, four of them before anyone asked.", "look": "The metro view: eight red crosses, and the final report", "focus": ["@spire-toolkit", "@spire-eqwd", "@spire-bench", "@spire-etch", "@spire-superpos", "@spire-geom1", "@spire-netv1", "@spire-wpg", "@spire-ph-record", "@chal-autonomy", "@spire-d5"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "guide", "text": "[warm] Now let's switch to another view of the same city: the metro map. Every study is a station, and every line is one phase of the work.", "do": [{"view": "metro"}]}, {"speaker": "sceptic", "text": "[dryly] Now the part most projects hide. Eight red crosses.", "do": [{"highlight": ["@spire-toolkit", "@spire-eqwd", "@spire-bench", "@spire-etch", "@spire-superpos", "@spire-geom1", "@spire-netv1", "@spire-wpg"]}]}, {"speaker": "guide", "text": "[thoughtful] It's the point of an AI scientist. A probe that fails is cheap, so you can afford many of them, and the record keeps every one."}, {"speaker": "sceptic", "text": "[curious] And the results you had already reported?"}, {"speaker": "guide", "text": "[honest] Five were taken back. Four of them we caught ourselves, before anyone asked; for the fifth, a colleague pointed out that rounding is deterministic, not noise.", "do": [{"highlight": ["@spire-wpg"]}]}, {"speaker": "guide", "text": "[thoughtful] So the deliverable is not the mechanism we set out to find, but a calibrated model, hard numbers for the hardware, and an honest list of what the data can and cannot tell. Negative results included.", "do": [{"highlight": ["@spire-r1", "@spire-r2", "@spire-r3", "@spire-r4", "@spire-r5", "@spire-r6", "@spire-r7", "@spire-d5"]}]}, {"speaker": "sceptic", "text": "[dryly] Honest. I'll take it."}], "quiz": [], "camera": {"center": [13.4, 52.5232645], "zoom": 12.6, "pitch": 45, "bearing": 0}}];

